import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("tmp", () => {
  it("works", async () => {
    const detach = searchService.registerSearchListeners();
    const t = await createTenant("tmpv", "growth");
    const other = await createTenant("tmpv2", "growth");
    const a = t.actors.member;
    const issue = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "Alpha" }));
    const issue2 = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "Beta" }));
    const oissue = await issueService.createIssue(other.actors.member, issueInput(other.org.id, other.project.id, { title: "Other" }));
    const oc = await commentService.createComment(other.actors.member, { orgId: other.org.id, issueId: oissue.id, body: "othercomment", parentId: null, mentionedUserIds: [] });
    const mk = (i: typeof issue, body: string, parentId: any = null) => commentService.createComment(a, { orgId: t.org.id, issueId: i.id, body, parentId, mentionedUserIds: [] });
    const c1 = await mk(issue, "c1 top");
    const r1 = await mk(issue, "r1 reply", c1.id);
    const c2 = await mk(issue2, "c2 other issue");
    expect((await issueService.getIssue(a, t.org.id, issue.id)).commentCount).toBe(2);
    await commentService.deleteComment(a, { orgId: t.org.id, commentId: c1.id });
    expect((await issueService.getIssue(a, t.org.id, issue.id)).commentCount).toBe(1);
    const q = (s: string) => searchRepo.searchDocuments({ orgId: t.org.id, q: s, kinds: [], limit: 25, cursor: null } as any).then((p) => p.total);
    expect(await q("c1 top")).toBe(0);
    expect(await q("r1 reply")).toBe(1);
    expect(await q("Alpha")).toBe(1);
    await issueService.archiveIssue(a, t.org.id, issue.id);
    expect(await q("r1 reply")).toBe(0);
    expect(await q("c2 other")).toBe(1);
    expect(await q("Alpha")).toBe(0);
    // many
    for (let i = 0; i < 230; i++) await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: `bulk ${i}` }), t.userIds.owner, await issueRepo.nextIssueNumber(t.org.id, t.project.id));
    for (let i = 0; i < 250; i++) await commentRepo.insertComment({ orgId: t.org.id, issueId: issue2.id, body: `long ${i}`, parentId: null, mentionedUserIds: [] }, t.userIds.owner);
    const rr = await commentRepo.insertComment({ orgId: t.org.id, issueId: issue2.id, body: "orphan reply", parentId: c1.id, mentionedUserIds: [] }, t.userIds.owner);
    // drift: stale docs
    await searchRepo.upsertSearchDocument(t.org.id, "comment", c1.id, "c1 top", null);
    await searchRepo.upsertSearchDocument(t.org.id, "issue", issue.id, "Alpha", t.project.id);
    await searchRepo.upsertSearchDocument(t.org.id, "comment", r1.id, "r1 reply", null);
    const before = await searchRepo.countIndexed(other.org.id);
    for (let n = 0; n < 2; n++) {
      const res = await runSearchReindexJob(t.org.id);
      expect(res.failed).toBe(0);
      expect(await q("bulk")).toBe(230);
      expect(await q("long")).toBe(250);
      expect(await q("orphan reply")).toBe(1);
      expect(await q("c1 top")).toBe(0);
      expect(await q("Alpha")).toBe(0);
      expect(await q("r1 reply")).toBe(0);
      expect(await q("c2 other")).toBe(1);
      expect(await searchRepo.countIndexed(t.org.id)).toBe(1 + 1 + 230 + 250 + 1 + 1); // project + Beta + bulk + long + orphan + c2
    }
    expect(await searchRepo.countIndexed(other.org.id)).toBe(before);
    detach();
    void rr; void oc;
  }, 60000);
});
EOF
